const SECOND_MS = 1000;
const MAX_DATE_MS = 8_640_000_000_000_000;

export const retryAfterMs = (
  value: string | null,
  now = Date.now(),
): number | undefined => {
  if (!value?.trim()) return undefined;
  const raw = value.trim();
  const isSeconds = /^\d+$/.test(raw);
  if (!isSeconds && !/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)[a-z]*(?:,| )/.test(raw))
    return undefined;
  const delay = isSeconds ? Number(raw) * SECOND_MS : Date.parse(raw) - now;
  if (!Number.isFinite(delay) || delay > MAX_DATE_MS - now) return undefined;
  return Math.max(0, delay);
};

export class ProviderRateLimit extends Error {
  constructor(readonly retryAfterMs?: number) {
    super('The provider temporarily limited requests');
    this.name = 'ProviderRateLimit';
  }
}

export const throwIfRateLimited = async (response: Response): Promise<void> => {
  if (response.status !== 429) return;
  const delay = retryAfterMs(response.headers.get('retry-after'));
  await response.body?.cancel();
  throw new ProviderRateLimit(delay);
};
